function e(e){let{horizontal:t,vertical:n}=e;return{kind:t===0?n===0?`degenerate`:`vertical`:n===0?`level`:`sloped`,degrees:Math.atan2(n,t)*180/Math.PI,percent:t===0?n===0?0:1/0:n/t*100,ratioRun:n===0?null:t/n}}function t(e){switch(e.kind){case`degenerate`:return`—`;case`level`:return`0.0°  0.0%  level`;case`vertical`:return`90.0°  vertical`;case`sloped`:return`${e.degrees.toFixed(1)}°  ${e.percent.toFixed(1)}%  1:${(e.ratioRun??0).toFixed(1)}`}}export{e as n,t};